onClick:
{{
  (async function() {
    const data = Get_Devis_Detail.data[0];

    // On sécurise la récupération de l'ID selon la casse de ta base de données
    const clientId = data?.ID_CLIENT || data?.ID_Client; 

    if (!clientId) {
      showAlert("Erreur : Impossible de trouver l'ID du client.", "error");
      return;
    }

    await storeValue('detail_client_id', clientId);
    // 🟢 CORRECTION : On indique bien qu'on vient de la page Détail Devis
    await storeValue('page_precedente', 'Détail Devis'); 
    await storeValue('id_precedent', appsmith.URL.queryParams.id);

    navigateTo('Détail Client');
  })()
}}
